ee:variables.ee:set-variable:
%dw 2.0
import backgroundTrades from max::market
output application/java
var closes = {(vars.dayPriceRows map {($.code): $.close})}
var favs = (vars.favorites groupBy $.customer_id) mapObject ((rows, cid) -> {(cid): rows map $.code})
var background = backgroundTrades(vars.day, vars.customers, favs, closes)
var planted = vars.planned map {customer_id: $.customer_id, code: $.code, side: $.side, qty: $.qty, price: closes[$.code],
    trade_date: vars.day, channel: 'ネット'}
var all = (background ++ planted) orderBy ($.customer_id ++ '|' ++ $.code ++ '|' ++ $.side)
---
all map ((t, i) -> t ++ {trade_id: 'T' ++ ((vars.lastTrade[0].n + i + 1) as String {format: '000000'})})
